// File: frontend/src/context/AuthContext.js

import React, { createContext, useState, useContext, useEffect } from 'react';
import axios from 'axios';

// 1. Create the context
const AuthContext = createContext(null);

// 2. Create the provider component
export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [token, setToken] = useState(localStorage.getItem('token'));
    const [loading, setLoading] = useState(true);

    // This effect runs on initial load to see if a token exists
    useEffect(() => {
        if (token) {
            // If we have a token, we could fetch user data here
            // For now, we'll just assume they are logged in.
            // A more robust solution would verify the token with the backend.
            axios.defaults.headers.common['x-auth-token'] = token;
            // For simplicity, we won't fetch user data here yet.
            // setUser({ name: "Logged In User" }); // Example
        }
        setLoading(false);
    }, [token]);

    // Login function
    const login = async (email, password) => {
        try {
            const res = await axios.post('/api/auth/login', { email, password });
            localStorage.setItem('token', res.data.token);
            setToken(res.data.token);
            axios.defaults.headers.common['x-auth-token'] = res.data.token;
            // You might want to fetch user data here and set it with setUser
        } catch (error) {
            // Re-throw the error to be handled by the component
            throw error;
        }
    };

    // Logout function
    const logout = () => {
        localStorage.removeItem('token');
        setToken(null);
        delete axios.defaults.headers.common['x-auth-token'];
        setUser(null);
    };

    const authContextValue = {
        token,
        user,
        login,
        logout,
        isAuthenticated: !!token, // True if token is not null
        loading,
    };

    return (
        <AuthContext.Provider value={authContextValue}>
            {children}
        </AuthContext.Provider>
    );


};



// 3. Create a custom hook to use the context easily
export const useAuth = () => {
    return useContext(AuthContext);
};
